Object.assign(SNIP,{"l36tm": "class BaoCao {\npublic:\n    void xuat() const {          // khuôn cố định, KHÔNG ảo: thứ tự các bước không đổi\n        dauTrang();\n        noiDung();               // phần riêng: lớp con quyết định\n        cout << \"-- het --\\n\";\n    }\n    virtual ~BaoCao() {}\nprotected:\n    virtual void dauTrang() const { cout << \"AMTS\\n\"; }   // có sẵn, được phép thay\n    virtual void noiDung() const = 0;                     // bắt buộc lớp con viết\n};", "l36syn": "class Hinh {                                   // lớp trừu tượng (abstract class)\npublic:\n    virtual double dienTich() const = 0;       // hàm ảo thuần túy: chỉ có tên, không có thân\n    virtual string ten() const = 0;\n    virtual ~Hinh() {}\n};\n\nclass Vuong : public Hinh {                    // lớp cụ thể: viết đủ mọi hàm = 0\n    double a;\npublic:\n    Vuong(double x) : a(x) {}\n    double dienTich() const override { return a * a; }\n    string ten() const override { return \"Vuong\"; }\n};\n\nHinh h;                 // LỖI: không tạo được đối tượng của lớp trừu tượng\nHinh* p = new Vuong(2); // được: con trỏ (hoặc tham chiếu) kiểu Hinh trỏ tới lớp con"});PRESET_NOTES["l36"]={"Ví dụ: Lớp trừu tượng Hinh": "Hinh không biết tính diện tích nên để = 0. moTa là hàm thường của Hinh nhưng gọi được ten() và dienTich(): lúc chạy, máy đi theo vptr tới bản của Vuong hoặc ChuNhat. Trong Hình động, vtable Vuong và ChuNhat đều đã điền đủ các ô.", "Lỗi: tạo đối tượng lớp trừu tượng": "g++: cannot declare variable 'h' to be of abstract type 'Hinh', kèm ghi chú liệt kê hàm còn thuần ảo. Hinh chỉ là bản hợp đồng; muốn có đối tượng, hãy tạo một lớp con viết đủ các hàm.", "Lỗi: lớp con quên một hàm thuần ảo": "Vuong viết dienTich nhưng quên chuVi, nên Vuong vẫn là lớp trừu tượng: invalid new-expression of abstract class type 'Vuong'. Ghi chú của g++ chỉ đúng hàm còn thiếu: Hinh::chuVi.", "Ví dụ: Giao diện ThongBao": "nhacLich chỉ biết ThongBao&: nó không cần biết bên dưới là email hay SMS. Thêm kênh mới (Zalo…) chỉ cần viết một lớp con, không sửa nhacLich. SMS cắt nội dung còn 10 ký tự: mỗi lớp con tự quyết cách gửi.", "Ví dụ: Mẫu khuôn BaoCao": "xuat() giữ thứ tự: đầu trang → nội dung → dòng kết. BaoCaoDiem chỉ viết noiDung (dùng dauTrang có sẵn); BaoCaoHocPhi thay cả dauTrang. Bên ngoài không gọi được dauTrang hay noiDung vì chúng là protected.", "Lỗi: gọi hàm thuần ảo trong hàm tạo": "Hàm tạo May gọi khoiDong, khoiDong gọi chay(). Lúc này phần Quat chưa được dựng, vptr đang trỏ vtable May, mà ô chay ở đó là = 0. Chương trình dừng: pure virtual method called. g++ không phát hiện được lúc biên dịch vì lời gọi đi gián tiếp qua khoiDong.", "Ví dụ: Cây biểu thức": "Mỗi nút của cây là một BieuThuc. Cong và Nhan giữ hai con trỏ BieuThuc* tới cây con, không cần biết cây con là số hay phép tính: gọi a->giaTri() là đủ, lời gọi tự đệ quy xuống tận lá. delete e gọi ~Cong, ~Cong lại delete hai cây con, nên cả cây được dọn sạch."};EX_HINTS["l36"]=[["Giao diện: virtual long long cuoc(long long km) const = 0; virtual string ten() const = 0; virtual ~PhuongTien() {}.", "XeBuyt không dùng km, nhưng vẫn phải nhận tham số km để ghi đè đúng chữ ký. Không dùng tới km thì bỏ tên tham số: long long cuoc(long long) const override, để g++ không cảnh báo -Wunused-parameter."], ["Mỗi lớp con chỉ cần một hàm: bool giu(long long x) const override.", "LocChiaHet cần thêm thành viên k và hàm tạo LocChiaHet(long long k)."], ["Tru và Nhan giống hệt Cong, chỉ đổi phép tính và dấu khi viết.", "Thứ tự quan trọng với phép trừ: lấy ra lần đầu là vế PHẢI, lần sau là vế TRÁI."]];
/* ===================== BÀI 36 · Lớp trừu tượng ===================== */
/* Bài 36 · Lớp trừu tượng
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P36=[{label:"Ví dụ: Lớp trừu tượng Hinh",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual double dienTich() const = 0;\n    virtual string ten() const = 0;\n    void moTa() const {\n        cout << ten() << \": \" << dienTich() << \"\\n\";\n    }\n    virtual ~Hinh() {}\n};\n\nclass Vuong : public Hinh {\n    double a;\npublic:\n    Vuong(double x) : a(x) {}\n    double dienTich() const override {\n        return a * a;\n    }\n    string ten() const override {\n        return \"Vuong\";\n    }\n};\n\nclass ChuNhat : public Hinh {\n    double a, b;\npublic:\n    ChuNhat(double x, double y) : a(x), b(y) {}\n    double dienTich() const override {\n        return a * b;\n    }\n    string ten() const override {\n        return \"ChuNhat\";\n    }\n};\n\nint main() {\n    vector<Hinh*> ds;\n    ds.push_back(new Vuong(3));\n    ds.push_back(new ChuNhat(2, 5));\n    for (Hinh* h : ds) {\n        h->moTa();\n    }\n    for (Hinh* h : ds) {\n        delete h;\n    }\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: tạo đối tượng lớp trừu tượng",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual double dienTich() const = 0;\n    virtual ~Hinh() {}\n};\n\nint main() {\n    Hinh h;\n    cout << h.dienTich() << \"\\n\";\n    return 0;\n}"},{label:"Lỗi: lớp con quên một hàm thuần ảo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass Hinh {\npublic:\n    virtual double dienTich() const = 0;\n    virtual double chuVi() const = 0;\n    virtual ~Hinh() {}\n};\n\nclass Vuong : public Hinh {\n    double a;\npublic:\n    Vuong(double x) : a(x) {}\n    double dienTich() const override {\n        return a * a;\n    }\n};\n\nint main() {\n    Hinh* p = new Vuong(2);\n    cout << p->dienTich() << \"\\n\";\n    delete p;\n    return 0;\n}"},{label:"Ví dụ: Giao diện ThongBao",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass ThongBao {\npublic:\n    virtual void gui(const string& noiDung) const = 0;\n    virtual string kenh() const = 0;\n    virtual ~ThongBao() {}\n};\n\nclass Email : public ThongBao {\n    string diaChi;\npublic:\n    Email(string d) : diaChi(d) {}\n    void gui(const string& noiDung) const override {\n        cout << \"[email \" << diaChi << \"] \" << noiDung << \"\\n\";\n    }\n    string kenh() const override {\n        return \"email\";\n    }\n};\n\nclass SMS : public ThongBao {\n    string so;\npublic:\n    SMS(string s) : so(s) {}\n    void gui(const string& noiDung) const override {\n        cout << \"[sms \" << so << \"] \" << noiDung.substr(0, 10) << \"\\n\";\n    }\n    string kenh() const override {\n        return \"sms\";\n    }\n};\n\nvoid nhacLich(const ThongBao& tb, const string& lop) {\n    tb.gui(\"Lop \" + lop + \" hoc luc 19h toi nay\");\n}\n\nint main() {\n    Email e(\"an@amts.vn\");\n    SMS s(\"0901234567\");\n    nhacLich(e, \"C++\");\n    nhacLich(s, \"C++\");\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Mẫu khuôn BaoCao",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass BaoCao {\npublic:\n    void xuat() const {\n        dauTrang();\n        noiDung();\n        cout << \"-- het --\\n\";\n    }\n    virtual ~BaoCao() {}\nprotected:\n    virtual void dauTrang() const {\n        cout << \"AMTS\\n\";\n    }\n    virtual void noiDung() const = 0;\n};\n\nclass BaoCaoDiem : public BaoCao {\n    int diem;\nprotected:\n    void noiDung() const override {\n        cout << \"Diem: \" << diem << \"\\n\";\n    }\npublic:\n    BaoCaoDiem(int d) : diem(d) {}\n};\n\nclass BaoCaoHocPhi : public BaoCao {\nprotected:\n    void dauTrang() const override {\n        cout << \"AMTS - Phong ke toan\\n\";\n    }\n    void noiDung() const override {\n        cout << \"Da dong hoc phi\\n\";\n    }\n};\n\nint main() {\n    BaoCaoDiem a(9);\n    BaoCaoHocPhi b;\n    a.xuat();\n    b.xuat();\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: gọi hàm thuần ảo trong hàm tạo",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass May {\npublic:\n    May() {\n        khoiDong();\n    }\n    void khoiDong() {\n        cout << \"Khoi dong: \";\n        chay();\n    }\n    virtual void chay() = 0;\n    virtual ~May() {}\n};\n\nclass Quat : public May {\npublic:\n    void chay() override {\n        cout << \"quat quay\\n\";\n    }\n};\n\nint main() {\n    Quat q;\n    q.chay();\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: Cây biểu thức",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nclass BieuThuc {\npublic:\n    virtual long long giaTri() const = 0;\n    virtual string viet() const = 0;\n    virtual ~BieuThuc() {}\n};\n\nclass So : public BieuThuc {\n    long long x;\npublic:\n    So(long long v) : x(v) {}\n    long long giaTri() const override {\n        return x;\n    }\n    string viet() const override {\n        return to_string(x);\n    }\n};\n\nclass Cong : public BieuThuc {\n    BieuThuc* a;\n    BieuThuc* b;\npublic:\n    Cong(BieuThuc* x, BieuThuc* y) : a(x), b(y) {}\n    long long giaTri() const override {\n        return a->giaTri() + b->giaTri();\n    }\n    string viet() const override {\n        return \"(\" + a->viet() + \" + \" + b->viet() + \")\";\n    }\n    ~Cong() {\n        delete a;\n        delete b;\n    }\n};\n\nclass Nhan : public BieuThuc {\n    BieuThuc* a;\n    BieuThuc* b;\npublic:\n    Nhan(BieuThuc* x, BieuThuc* y) : a(x), b(y) {}\n    long long giaTri() const override {\n        return a->giaTri() * b->giaTri();\n    }\n    string viet() const override {\n        return \"(\" + a->viet() + \" * \" + b->viet() + \")\";\n    }\n    ~Nhan() {\n        delete a;\n        delete b;\n    }\n};\n\nint main() {\n    BieuThuc* e = new Cong(new So(2), new Nhan(new So(3), new So(4)));\n    cout << e->viet() << \" = \" << e->giaTri() << \"\\n\";\n    delete e;\n    return 0;\n}",viz:[{type:"mem"}]}];
const sim36=makeSim2(document.getElementById("sim-l36"),{id:"s36",presets:P36});
makeEx2(document.getElementById("ex-l36"),sim36,[{t:"Cước phương tiện",d:"Viết giao diện <code>PhuongTien<\/code> với hai hàm thuần ảo <code>long long cuoc(long long km) const<\/code>, <code>string ten() const<\/code> và hàm hủy ảo. Ba lớp con: <code>XM<\/code> → <code>XeMay<\/code>, 4000 đồng/km; <code>TX<\/code> → <code>Taxi<\/code>, 12000 mở cửa + 15000 đồng/km; <code>BUS<\/code> → <code>XeBuyt<\/code>, vé 7000 đồng không phụ thuộc km. Nhập n rồi n dòng <code>loai km<\/code>. In từng chuyến <code>ten cuoc<\/code>, rồi <code>Tong: ...<\/code> và <code>Re nhat: ten<\/code> (bằng nhau lấy chuyến nhập trước).",tests:[{in:"3\nXM 5\nTX 3\nBUS 20",out:"XeMay 20000\nTaxi 57000\nXeBuyt 7000\nTong: 84000\nRe nhat: XeBuyt"},{in:"1\nTX 0",out:"Taxi 12000\nTong: 12000\nRe nhat: Taxi"},{in:"3\nXM 2\nBUS 9\nTX 0",out:"XeMay 8000\nXeBuyt 7000\nTaxi 12000\nTong: 27000\nRe nhat: XeBuyt"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass PhuongTien {\npublic:\n    // hai hàm thuần ảo: cuoc(km), ten(); hàm hủy ảo\n};\n\n// XeMay, Taxi, XeBuyt\n\nint main() {\n    int n;\n    cin >> n;\n    vector<PhuongTien*> ds;\n    vector<long long> km;\n    for (int i = 0; i < n; i++) {\n        string loai;\n        long long k;\n        cin >> loai >> k;\n        // tạo đúng loại phương tiện, lưu km\n    }\n    // in từng chuyến, tổng, chuyến rẻ nhất; giải phóng bộ nhớ\n    return 0;\n}",need:/virtual\s+long\s+long\s+cuoc\s*\([^)]*\)\s*const\s*=\s*0[\s\S]*virtual\s+string\s+ten\s*\(\s*\)\s*const\s*=\s*0/,needMsg:"PhuongTien phải là giao diện: cuoc và ten là hàm thuần ảo (= 0)."},{t:"Bộ lọc số",d:"Lớp trừu tượng <code>BoLoc<\/code> (đã viết sẵn) có hàm thuần ảo <code>bool giu(long long x) const<\/code> và hàm thường <code>loc(a)<\/code> trả về các phần tử được giữ, theo đúng thứ tự. Viết ba lớp con: <code>LocChan<\/code> (giữ số chẵn), <code>LocDuong<\/code> (giữ số &gt; 0), <code>LocChiaHet<\/code> (giữ số chia hết cho k, k nhập kèm, k ≠ 0). Nhập n, dãy n số, rồi q yêu cầu: <code>chan<\/code>, <code>duong<\/code> hoặc <code>chiahet k<\/code>. Với mỗi yêu cầu in các số được giữ cách nhau một dấu cách, hoặc <code>rong<\/code> nếu không còn số nào.",tests:[{in:"6\n4 -3 0 7 -8 9\n3\nchan\nduong\nchiahet 3",out:"4 0 -8\n4 7 9\n-3 0 9"},{in:"2\n1 3\n2\nchan\nchiahet 5",out:"rong\nrong"},{in:"1\n-6\n2\nduong\nchiahet 2",out:"rong\n-6"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass BoLoc {\npublic:\n    virtual bool giu(long long x) const = 0;\n    vector<long long> loc(const vector<long long>& a) const {\n        vector<long long> kq;\n        for (long long x : a) {\n            if (giu(x)) kq.push_back(x);\n        }\n        return kq;\n    }\n    virtual ~BoLoc() {}\n};\n\n// LocChan, LocDuong, LocChiaHet\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (int i = 0; i < n; i++) cin >> a[i];\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string lenh;\n        cin >> lenh;\n        // tạo bộ lọc phù hợp (BoLoc* b = new ...), gọi b->loc(a), in kết quả, delete b\n    }\n    return 0;\n}",need:/class\s+LocChan\s*:\s*public\s+BoLoc[\s\S]*class\s+LocChiaHet\s*:\s*public\s+BoLoc/,needMsg:"Hãy viết LocChan, LocDuong, LocChiaHet kế thừa public BoLoc."},{t:"Tính biểu thức hậu tố",d:"Biểu thức hậu tố (ký pháp Ba Lan ngược) viết toán tử sau hai toán hạng: <code>2 3 4 * +<\/code> nghĩa là 2 + 3 × 4. Dùng cây biểu thức như ví dụ mô phỏng: lớp trừu tượng <code>BieuThuc<\/code> (<code>giaTri()<\/code>, <code>viet()<\/code>), lớp <code>So<\/code> và <code>Cong<\/code> đã có; viết thêm <code>Tru<\/code> và <code>Nhan<\/code>. Nhập n rồi n phần tử (số nguyên không âm hoặc <code>+ - *<\/code>), biểu thức luôn hợp lệ. Dựng cây bằng một <code>vector&lt;BieuThuc*&gt;<\/code> làm ngăn xếp: gặp số thì đẩy vào; gặp phép toán thì lấy ra hai cây (cây lấy ra sau là vế trái), ghép thành nút mới rồi đẩy lại. In dạng có ngoặc đầy đủ, sau đó in giá trị.",tests:[{in:"5\n2 3 4 * +",out:"(2 + (3 * 4))\n14"},{in:"7\n10 2 3 + - 4 *",out:"((10 - (2 + 3)) * 4)\n20"},{in:"3\n1000000000 1000000000 *",out:"(1000000000 * 1000000000)\n1000000000000000000"},{in:"1\n7",out:"7\n7"}],start:"#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nclass BieuThuc {\npublic:\n    virtual long long giaTri() const = 0;\n    virtual string viet() const = 0;\n    virtual ~BieuThuc() {}\n};\n\nclass So : public BieuThuc {\n    long long x;\npublic:\n    So(long long v) : x(v) {}\n    long long giaTri() const override { return x; }\n    string viet() const override { return to_string(x); }\n};\n\nclass Cong : public BieuThuc {\n    BieuThuc* a;\n    BieuThuc* b;\npublic:\n    Cong(BieuThuc* x, BieuThuc* y) : a(x), b(y) {}\n    long long giaTri() const override { return a->giaTri() + b->giaTri(); }\n    string viet() const override { return \"(\" + a->viet() + \" + \" + b->viet() + \")\"; }\n    ~Cong() { delete a; delete b; }\n};\n\n// viết Tru, Nhan theo mẫu Cong\n\nint main() {\n    int n;\n    cin >> n;\n    vector<BieuThuc*> st;\n    for (int i = 0; i < n; i++) {\n        string t;\n        cin >> t;\n        // số: st.push_back(new So(stoll(t)));\n        // phép toán: lấy phai = st.back(), pop; trai = st.back(), pop; đẩy nút mới\n    }\n    BieuThuc* e = st.back();\n    cout << e->viet() << \"\\n\" << e->giaTri() << \"\\n\";\n    delete e;\n    return 0;\n}",need:/class\s+Tru\s*:\s*public\s+BieuThuc[\s\S]*class\s+Nhan\s*:\s*public\s+BieuThuc/,needMsg:"Hãy viết class Tru và class Nhan kế thừa public BieuThuc."}]);

makeQuiz("quiz36","score36",[{"q": "Lớp nào sau đây là lớp trừu tượng?", "o": ["Lớp có ít nhất một hàm ảo", "Lớp có ít nhất một hàm ảo thuần túy chưa được ghi đè", "Lớp không có thành viên dữ liệu", "Lớp có hàm hủy ảo"], "a": 1, "e": "Chỉ hàm thuần ảo (= 0) chưa được ghi đè mới làm lớp thành trừu tượng."}, {"q": "<code>Hinh<\/code> là lớp trừu tượng. Câu nào <b>hợp lệ<\/b>?", "o": ["Hinh h;", "Hinh* p = new Hinh();", "void f(const Hinh&amp; h);", "void f(Hinh h);"], "a": 2, "e": "Tham chiếu và con trỏ tới lớp trừu tượng dùng được; tạo đối tượng hay truyền theo giá trị thì không."}, {"q": "<code>Con : public Cha<\/code>, Cha có hai hàm thuần ảo f, g. Con chỉ viết f. Điều gì xảy ra khi viết <code>Con c;<\/code>?", "o": ["Chạy bình thường, g dùng bản rỗng", "Lỗi biên dịch: Con vẫn là lớp trừu tượng vì còn g", "Lỗi lúc chạy khi gọi g", "Con tự lấy bản g của Cha"], "a": 1, "e": "Con còn thừa kế g = 0 nên vẫn trừu tượng, g++ báo lỗi và chỉ ra g."}, {"q": "Trong mẫu khuôn (template method), hàm giữ thứ tự các bước (như <code>xuat()<\/code>) thường là:", "o": ["Hàm thuần ảo", "Hàm thường (không ảo) của lớp cha", "Hàm tạo của lớp con", "Hàm static"], "a": 1, "e": "Hàm khuôn không ảo để lớp con không đổi được thứ tự; các bước bên trong mới là hàm ảo."}]);

